import {internalADCSource} from './stm32-internal-example.js';
import {blankPinConfig} from './stm32-pin-config.js';
import {STM_OTG_DEVICE} from './stm32-otg-example.js';
import {STM_CAN_LOOPBACK,STM_USB_DEVICE} from './stm32-bus-examples.js';
import {STM_PY_HELPER,STM_PY_ENV} from './stm32-python-examples.js';
import {PY_SHT31} from './python-examples.js';
import {createSTMLab,STM_FEATURED_EXAMPLES} from './stm32-labs.js';
import {labelWire} from './net-label-tools.js';
import {spaceNativeParts,outerBoardPads} from './wire-router.js';
import {C_SENSOR_EXAMPLES,cBusFiles} from './c-sensor-examples.js';
import {espExampleCircuit} from './esp-circuit-examples.js';
import {STM32_BOARDS} from './stm32-boards.js';
import {emptyProject} from './templates.js';
import {placementCandidate,attachPlacement} from './mounting.js';
import {pinPoint,localPoint} from './geometry.js';
import {componentDefinition} from './core.js';
export const STM_EXAMPLES=[{id:"internal-adc",name:"Dahili sıcaklık / VREF / VBAT",detail:"Native ADC1 · register / nominal model"},{id:"can-loopback",f103Only:true,name:"F103 · CAN loopback / IRQ",detail:"3 TX mailbox · filtre · RX FIFO · dahili test"},{id:"usb-device",name:"USB aygıtı / bulk echo",detail:"Sanal USB host · descriptor / adres / EP1 · PMA / OTG FIFO + IRQ"},...STM_FEATURED_EXAMPLES,...C_SENSOR_EXAMPLES,{id:'blink',name:'C17 · Breadboard LED',detail:'PA0 · gerçek ARM GPIO'},{id:'button',name:'C17 · Buton + LED',detail:'PA1 pull-up / PA0 LED'},{id:'bluetooth',name:'C17 · Bluetooth sanal ağ',detail:'GPIO UART · PB8/PB9 · bilgisayar echo'},{id:'labels',name:'C17 · Net label LED',detail:'Breadboard olmadan etiketlerle bağlantı'},{id:'echo',name:'C17 · Seri terminal',detail:'USART1 / Nucleo USART2 VCP'}];
export const availableSTMExamples=(board,language='c')=>STM_EXAMPLES.filter(e=>(!e.f103Only||STM32_BOARDS[board]?.cpu==='cortex-m3')&&(language!=='micropython'||['environment','empty','blink','sht31','adc'].includes(e.id)));
function createSTMProjectRaw({name='Yeni STM32 projesi',board='stm32f103c8',language='c',starter='blink'}={}){const b=STM32_BOARDS[board];if(!b||language!=='c'||!['empty',...STM_EXAMPLES.map(e=>e.id)].includes(starter))throw Error('STM32 kart/dil/örnek seçimi desteklenmiyor.');const p=emptyProject();p.name=name;p.language='c';p.settings.probe='PA0';p.settings.tracePins=['PA1','PB6','PB7'];p.components=[{id:'mcu',type:'board',x:35,y:65,rotation:0,params:{model:board}},{id:'bb1',type:'breadboard',x:Math.max(420,b.width*1.35+130),y:150,rotation:0,params:{}}];p.wires=[];if(starter==='internal-adc'){p.components=p.components.filter(c=>c.type==='board');p.settings.stm32Pins=blankPinConfig();p.settings.tracePins=[];p.code=internalADCSource(b.cpu==='cortex-m4f');return p;}if(['can-loopback','usb-device'].includes(starter)){if(starter==='can-loopback'&&b.cpu==='cortex-m4f')throw Error('Bu örnek F103 bxCAN denetleyicisi gerektirir.');p.components=p.components.filter(c=>c.type==='board');p.code=starter==='can-loopback'?STM_CAN_LOOPBACK:b.cpu==='cortex-m4f'?STM_OTG_DEVICE:STM_USB_DEVICE;p.settings.tracePins=[];return p;}if(starter==='bluetooth')return bluetoothProject(p,b);if(starter==='labels'){const q=createSTMProjectRaw({name,board,language,starter:'blink'});for(const c of q.components)delete c.mount;q.components=q.components.filter(c=>c.type!=='breadboard');q.components.find(c=>c.id==='r1').x=b.width*1.35+310;q.components.find(c=>c.id==='r1').y=100;q.components.find(c=>c.id==='led1').x=b.width*1.35+330;q.components.find(c=>c.id==='led1').y=300;outerBoardPads(q);for(const id of q.wires.map(w=>w.id))labelWire(q,id);return q;}if(C_SENSOR_EXAMPLES.some(e=>e.id===starter))return sensorProject(p,board,starter);const connect=(a,c,color='#14b8a6')=>p.wires.push({id:'w'+p.wires.length,from:a,to:c,color,points:[]});if(['blink','button'].includes(starter)){p.components.push({id:'r1',type:'resistor',x:480,y:350,rotation:0,params:{ohms:220}},{id:'led1',type:'led',x:650,y:330,rotation:0,params:{color:'red'}});const endpoint=pin=>{const def=b.pins.find(p=>p.net===pin&&p.connectable!==false);return 'mcu:'+def.id;};connect(endpoint('PA0'),'r1:1');connect('r1:2','led1:A');connect('led1:K','mcu:GND');for(const[id,hole,pin]of[['r1','c5','1'],['led1','j11','A']]){const c=p.components.find(c=>c.id===id),def=componentDefinition(c).pinDefs.find(p=>p.id===pin),target=pinPoint(p,'bb1:'+hole),local=localPoint(c,def.x,def.y);c.x=target.x-local.x;c.y=target.y-local.y;attachPlacement(c,placementCandidate(p,c,{radius:.1}));}if(starter==='button'){p.components.push({id:'btn1',type:'button',x:650,y:420,rotation:0,params:{pressed:false}});connect(endpoint('PA1'),'btn1:1','#3b82f6');connect('btn1:2','mcu:GND','#3b82f6');}}
p.code=starter==='empty'?'#include <cf_hal.h>\nint main(void){for(;;){} }\n':starter==='echo'?`#include <cf_hal.h>\n#include <stdio.h>\nint main(void){cf_uart_begin(115200);puts("STM32 UART READY");for(;;){int c=cf_uart_read();if(c>=0)cf_uart_write(c);}}\n`:starter==='button'?`#include <cf_hal.h>\n#include <stdio.h>\nint main(void){cf_gpio_mode(PA0,CF_OUTPUT);cf_gpio_mode(PA1,CF_INPUT_PULLUP);cf_uart_begin(115200);puts("STM32 BUTTON READY");int last=-1;for(;;){int pressed=!cf_gpio_read(PA1);cf_gpio_write(PA0,pressed);if(pressed!=last){printf("BUTTON=%d\\r\\n",pressed);last=pressed;}}}\n`:`#include <cf_hal.h>\n#include <stdio.h>\nint main(void){cf_gpio_mode(PA0,CF_OUTPUT);cf_uart_begin(115200);puts("CircuitForge STM32 C17");for(;;){cf_gpio_write(PA0,1);puts("STM LED ON");cf_delay_ms(20);cf_gpio_write(PA0,0);puts("STM LED OFF");cf_delay_ms(20);}}\n`;return p;}

function sensorProject(p,board,id){const b=STM32_BOARDS[board],e=C_SENSOR_EXAMPLES.find(e=>e.id===id),c=espExampleCircuit(e.circuit,'esp32c3'),map=id==='sht31'?{GPIO4:'PB7',GPIO5:'PB6'}:{GPIO4:'PA5',GPIO6:'PA6',GPIO5:'PA7',GPIO7:'PA4'};p.components=[...c.components.map(c=>({...c,rotation:0,params:c.type==='board'?{model:board}:c.params})),{id:'bb1',type:'breadboard',x:860,y:180,rotation:0,params:{}}];const bind=endpoint=>{if(!endpoint.startsWith('mcu:'))return endpoint;const old=endpoint.slice(4),net=map[old]||old,pin=b.pins.find(p=>p.connectable!==false&&(p.net||p.id)===net);if(!pin)throw Error('STM32 sensör örneğinde pin bulunamadı: '+net);return 'mcu:'+pin.id;};p.wires=c.wires.map(w=>({...w,from:bind(w.from),to:bind(w.to),points:[]}));p.files=cBusFiles();p.code=e.code.replace(/enum \{ SDA = 4, SCL = 5 \};/,'enum { SDA = PB7, SCL = PB6 };').replace(/enum \{ SCK = 4, MISO = 6, MOSI = 5, CS = 7 \};/,'enum { SCK = PA5, MISO = PA6, MOSI = PA7, CS = PA4 };');p.settings.probe=id==='sht31'?'PB7':'PA5';return p;}

export function createSTMProject(options){const language=options?.language??'c';if(!['c','cpp','micropython'].includes(language))throw Error('STM32 C17/C++17 dili desteklenir.');if(language==='micropython'&&!['empty','blink','sht31','adc','environment'].includes(options?.starter||'blink'))throw Error('MicroPython için çevre istasyonu/LED/sensör örneği seçin.');const opts={...options,language:'c'},p=STM_FEATURED_EXAMPLES.some(e=>e.id===opts.starter)?createSTMLab(opts):spaceNativeParts(createSTMProjectRaw(opts));if(language==='micropython'){p.language=language;delete p.settings.stm32Pins;p.files=[];if(opts.starter==='environment'){p.code=STM_PY_ENV;p.files=[{name:'cf_station.py',content:STM_PY_HELPER}];}else if(opts.starter==='sht31')p.code=PY_SHT31.replace('Pin(4)',"Pin('PB7')").replace('Pin(5)',"Pin('PB6')");else if(opts.starter==='empty')p.code='# STM32 MicroPython · Pin / ADC / SoftI2C / SoftSPI\n';else if(opts.starter==='adc')p.code=STM_PY_HELPER+"\nprint('ADC=',read_adc())\n";else p.code="from machine import Pin\nimport js\nled=Pin('PA0',Pin.OUT,value=0)\nwhile True:\n    led.on()\n    print('PY LED ON')\n    await js.cf.sleep(100)\n    led.off()\n    print('PY LED OFF')\n    await js.cf.sleep(100)\n";}if(language==='cpp'){p.language='cpp';for(const f of p.files||[])if(f.name.endsWith('.h')){const split=f.content.indexOf('\n'),first=f.content.slice(0,split+1),rest=f.content.slice(split+1);f.content=first+'#ifdef __cplusplus\nextern "C" {\n#endif\n'+rest+'\n#ifdef __cplusplus\n}\n#endif\n';}}return p;}

function bluetoothProject(p,b){p.components=p.components.filter(c=>c.type!=='breadboard');p.components.push({id:'bt1',type:'bluetooth',x:b.width*1.35+260,y:140,rotation:0,params:{name:'STM32-BLE-UART',baud:9600}});const pin=net=>'mcu:'+b.pins.find(p=>p.connectable!==false&&(p.net||p.id)===net).id;p.wires=[['3V3','VCC'],['GND','GND'],['PB8','RX'],['PB9','TX'],['PB5','STATE']].map(([net,terminal],i)=>({id:'btw'+i,from:pin(net),to:'bt1:'+terminal,color:net==='GND'?'#64748b':net==='3V3'?'#ef4444':'#14b8a6',points:[]}));p.settings.probe='PB8';p.settings.tracePins=['PB9','PB5'];p.code=BT_CODE;return p;}
const BT_CODE=String.raw`#include <cf_hal.h>
#include <stdio.h>
/* CF-BLE-UART: software UART 9600 8N1, 3.3V. Not an STM32 BLE radio. */
enum { TX=PB8, RX=PB9, STATE=PB5 };
static void bt_write(unsigned char c){cf_gpio_write(TX,0);cf_delay_us(104);for(int i=0;i<8;i++){cf_gpio_write(TX,(c>>i)&1);cf_delay_us(104);}cf_gpio_write(TX,1);cf_delay_us(104);}
static int bt_read(void){if(cf_gpio_read(RX))return -1;cf_delay_us(156);unsigned c=0;for(int i=0;i<8;i++){c|=cf_gpio_read(RX)<<i;cf_delay_us(104);}if(!cf_gpio_read(RX))return -1;return c;}
int main(void){cf_gpio_mode(TX,CF_OUTPUT);cf_gpio_write(TX,1);cf_gpio_mode(RX,CF_INPUT_PULLUP);cf_gpio_mode(STATE,CF_INPUT);cf_uart_begin(115200);puts("VIRTUAL BLUETOOTH READY");int linked=0,n=0;char line[128];for(;;){int state=cf_gpio_read(STATE);if(state&&!linked){const char *s="STM32 BLE READY\r\n";while(*s)bt_write(*s++);puts("VIRTUAL CONNECTED");}if(!state)n=0;linked=state;if(state){int c=bt_read();if(c>=0){if(n<120)line[n++]=(char)c;if(c==10||n>=120){for(int i=0;i<n;i++){bt_write(line[i]);cf_uart_write(line[i]);}n=0;}}}}}
`;
